const rtdal009476Source0002 = `prep_names <- function(..., self) {
  new_nms <- unlist(rlang::list2(...))

  if (rlang::is_named(new_nms)) {
    if (!self$has_names()) {
      runtime_error("The tensor doesn't have names so you can't rename a dimension.")
    }

    nms <- self$names
    nms[which(nms == names(new_nms))] <- new_nms
  } else {
    nms <- new_nms
  }
  nms
}`

const rtdal009476Source0003 = `torch_tensor <- function(data, dtype = NULL, device = NULL, requires_grad = FALSE,
                         pin_memory = FALSE) {
  Tensor$new(data, dtype, device, requires_grad, pin_memory)
}`

const rtdal009476Source0005 = `as_array.default <- function(x) {
  base::as.array(x)
}`

const rtdal009476Source0006 = `as.array.torch_tensor <- function(x, ...) {
  as_array(x)
}`

const rtdal009476Source0007 = `as.matrix.torch_tensor <- function(x, ...) {
  as.matrix(as_array(x))
}`

const rtdal009476Source0008 = "as_array_impl <- function(x) {\n  if (x$is_sparse() || x$is_sparse_csr()) {\n    cli_abort(c(\n      \"Sparse tensors are not supported for as_array conversion.\",\n      i = \"Use `as_array(x$to_dense())` to convert to a dense tensor first.\"\n    ))\n  }\n\n  # move tensor to cpu before copying to R\n  x <- x$cpu()\n\n  if (x$is_complex()) {\n    out <- complex(\n      real = as.array(x$real),\n      imaginary = as.array(x$imag)\n    )\n    dim(out) <- dim(x)\n    return(out)\n  }\n\n  a <- cpp_as_array(x)\n\n  if (length(a$dim) <= 1L) {\n    out <- a$vec\n  } else if (length(a$dim) == 2L) {\n    out <- t(matrix(a$vec, ncol = a$dim[1], nrow = a$dim[2]))\n  } else {\n    out <- aperm(array(a$vec, dim = rev(a$dim)), seq(length(a$dim), 1))\n  }\n\n  if (x$dtype == torch_long() && !inherits(out, \"integer64\")) {\n    class(out) <- c(class(out), \"integer64\")\n  }\n\n  out\n}"

const rtdal009476Source0009 = `as_array.torch_tensor <- function(x) {
  # dequantize before converting
  if (x$is_quantized()) {
    x <- x$dequantize()
  }

  # auto convert to int32 if long.
  if (x$dtype == torch_long()) {
    if ((x > .Machine$integer.max)$any()$item()) {
      warn("Converting integers > .Machine$integer.max is undefined and returns wrong results. Use as.integer64(x)")
    }

    x <- x$to(dtype = torch_int32())
  }


  out <- as_array_impl(x)

  out
}`

const rtdal009476Source0012 = `as.integer64.torch_tensor <- function(x, keep.names = FALSE, ...) {
  x <- x$to(dtype = torch_long())
  as_array_impl(x)
}`

const rtdal009476Source0013 = `make_str_torch_tensor <- function(object) {
  dtype <- object$dtype$.type()

  dims <- dim(object)
  dims <- paste(paste0("1:", dims), collapse = ", ")

  out <- paste0(dtype, " [", dims, "]")
  out
}`

const rtdal009476Source0014 = `str.torch_tensor <- function(object, ...) {
  out <- make_str_torch_tensor(object)
  cat(out)
  cat("\n")
}`

const rtdal009476Source0015 = `Tensor$set("active", "ptr", function() {
  self
})`

const rtdal009476Source0019 = `head.torch_tensor <- function(x, n = 6, ...) {
  index <- torch_tensor(seq_len(min(n, x$size(1))))
  torch_index_select(x, dim = 1, index = index)
}`

const rtdal009476Source0020 = `tail.torch_tensor <- function(x, n = 6, ...) {
  sz <- x$size(1)
  index <- seq.int(max(1, sz - n + 1), sz)
  torch_index_select(x, dim = 1, index = index)
}`

