const rtdal009478Source0001 = `jit_trace <- function(func, ..., strict = TRUE, respect_mode = TRUE) {
  rlang::check_dots_unnamed() # we do not support named arguments

  if (inherits(func, "nn_module")) {
    if (inherits(func, "nn_module_generator")) {
      value_error("You must initialize the nn_module before tracing.")
    }

    args <- list(
      mod = func,
      forward = rlang::list2(...),
      strict = strict,
      respect_mode = respect_mode
    )
    return(do.call(jit_trace_module, args))
  }

  if (!rlang::is_closure(func)) {
    value_error("jit_trace needs a function or nn_module.")
  }
  tr_fn <- make_traceable_fn(func)

  ptr <- cpp_trace_function(tr_fn, list(...), .compilation_unit, strict, name = "name")
  new_script_function(ptr)
}`

const rtdal009478Source0002 = `jit_load <- function(path, ...) {
  path <- normalizePath(path, mustWork = TRUE)
  cpp_jit_load(path)
}`

const rtdal009478Source0003 = "jit_save <- function(obj, path, ...) {\n  path <- normalizePath(path, mustWork = FALSE)\n\n  if (inherits(obj, \"script_function\")) {\n    obj$save(path)\n  } else if (inherits(obj, \"script_module\")) {\n    obj$..ptr..()$save(path)\n  } else {\n    value_error(\"Only `script_function` or `script_module` can be saved with `jit_save`.\")\n  }\n\n  invisible(obj)\n}"

const rtdal009478Source0004 = "jit_serialize <- function(obj) {\n  if (inherits(obj, \"script_module\")) {\n    obj$..ptr..()$serialize()\n  } else {\n    value_error(\"Only `script_module` can be serialized with `jit_serialize`.\")\n  }\n}"

