const rtdal009479Source0013 = `translate_increase_group <- function(msg, regex, ifpos=TRUE) {
  if (!grepl(regex, msg))
    return(msg)
  
  values <- regmatches(msg, regexec2(regex, msg))
  values <- lapply(values, function(x) {
    x <- as.integer(x)
    if (ifpos) 
      as.character(ifelse(x >= 0, x + 1, x))
    else
      as.character(x+1)
  })
  
  regmatches(msg, regexec2(regex, msg)) <- values
  msg
}`

