const rtdal009480Source0001 = `torch_iinfo <- function(dtype) {
  if (dtype == torch_int32() || dtype == torch_qint32()) {
    list(
      bits = 32,
      max = bit64::as.integer64("2147483647"),
      min = bit64::as.integer64("-2147483648")
    )
  } else if (dtype == torch_int64()) {
    list(
      bits = 64,
      max = bit64::as.integer64("9223372036854775807"),
      min = bit64::as.integer64("-9223372036854775808")
    )
  } else if (dtype == torch_int16()) {
    list(
      bits = 16,
      max = 32767L,
      min = -32768L
    )
  } else if (dtype == torch_int8() || dtype == torch_qint8()) {
    list(
      bits = 8,
      max = 127L,
      min = -128L
    )
  } else if (dtype == torch_uint8() || dtype == torch_quint8()) {
    list(
      bits = 8,
      max = 255L,
      min = 0L
    )
  } else {
    value_error("dtype must be an integer type.")
  }
}`

