const rtdal009488Source0003 = `add_class_definition <- function(r6_class_generator) {
  .new <- r6_class_generator$new
  .class_def <- r6_class_generator
  .wrapped_new <- function(...) {
    .object <- .new(...)
    .object$.__enclos_env__$self$class_def <- .class_def
    .object
  }
  r6_class_generator$unlock()
  r6_class_generator$new <- .wrapped_new
  r6_class_generator$lock()
  r6_class_generator
}`

const rtdal009488Source0004 = "create_class <- function(name, inherit, ..., private, active, parent_env,\n                         attr_name, constructor_class = NULL) {\n  args <- list(...)\n\n  if (!is.null(attr(inherit, attr_name))) {\n    inherit <- attr(inherit, attr_name)\n  }\n\n  e <- new.env(parent = parent_env)\n  e$inherit <- inherit\n\n  .__class__ <- R6::R6Class(\n    classname = name,\n    lock_objects = FALSE,\n    inherit = inherit,\n    public = args,\n    private = private,\n    active = active,\n    parent_env = e\n  )\n\n  init <- get_init(.__class__)\n  # same signature as the init method, but calls with dataset$new.\n  # NOTE: the R6 class is stored as `.__class__` rather than a short name\n  # like `d` to avoid being shadowed when a user names their `initialize`\n  # parameter `d` (or any other short letter).\n  f <- rlang::new_function(\n    args = rlang::fn_fmls(init),\n    body = rlang::expr({\n      .__class__$new(!!!rlang::fn_fmls_syms(init))\n    })\n  )\n\n  attr(f, attr_name) <- .__class__\n  if (!is.null(constructor_class)) {\n    class(f) <- constructor_class\n  }\n\n  f\n}"

const rtdal009488Source0006 = `head2 <- function(x, n) {
  if (n > 0) {
    utils::head(x, n = n)
  } else {
    utils::head(x, n = length(x) + n)
  }
}`

const rtdal009488Source0007 = `seq2 <- function(start, end, by = 1L) {
  if ((end - start) < by && (end - start != 0)) {
    return(integer())
  } else {
    seq(start, end, by = by)
  }
}`

const rtdal009488Source0009 = `math_to_rd_impl <- function(tex, ascii = tex, displayMode = TRUE, ..., include_css = TRUE) {

  if (in_pkgdown()) {
    html <- katex::katex_html(tex,
                              include_css = include_css, displayMode = displayMode, ...,
                              preview = FALSE
    )
  } else {
    html <- "<p>Math could not be displayed. Please visit the package website.</p>"
  }

  html_out <- paste("\\if{html}{\\out{", html, "}}", sep = "\n")
  # We won't show the equations in latex mode because of limitted support.
  latex_out <- paste("\\if{latex,text}{\\out{", ascii, "}}", sep = "\n")
  rd <- paste(html_out, latex_out, sep = "\n")
  if (identical(.Platform$OS.type, "windows") && getRversion() < "4.1.1") {
    # https://bugs.r-project.org/bugzilla/show_bug.cgi?id=18152
    rd <- enc2native(rd)
  }
  structure(rd, class = "Rdtext")
}`

const rtdal009488Source0010 = `math_to_rd <- function(tex, ascii = tex, displayMode = TRUE, ..., include_css = TRUE) {
  if (tex == ascii) {
    ascii <- "Equation not displayed. Please find it in 'https://torch.mlverse.org/docs'"
  }

  if (rlang::is_installed("katex")) {
    math_to_rd_impl(tex, ascii, displayMode = displayMode, ..., include_css = include_css)
  } else {
    rd <- "\\out{Equation not displayed. Install 'katex' then re-install 'torch'.}"
    structure(rd, class = "Rdtext")
  }
}`

