const rtdal009491Source0001 = `torch_lu <- function(A, pivot = TRUE, get_infos = FALSE, out = NULL) {
  # If get_infos is True, then we don't need to check for errors and vice versa
  result <- torch__lu_with_info(A, pivot, get_infos)

  if (!is.null(out)) {
    if (!is.list(out)) {
      type_error("argument 'out' must be a list of Tensors.")
    }

    if (length(out) - as.integer(get_infos) != 2) {
      value_error(
        "expected tuple of {2 + as.integer(get_infos)} elements but got {length(out)}"
      )
    }

    for (i in seq_len(out)) {
      out[[i]] <- out[[i]]$resize_as_(result[[i]])$copy_(result[[i]])
    }

    return(out)
  }


  if (get_infos) {
    return(result)
  } else {
    return(result[1:2])
  }
}`

