const rtdal009505Source0002 = `test_that("comparison takes requires_grad into account", {
  testthat::local_edition(3)
  expect_equal(
    torch_tensor(1)$requires_grad_(FALSE),
    torch_tensor(1)$requires_grad_(FALSE)
  )
  expect_equal(
    torch_tensor(1)$requires_grad_(TRUE),
    torch_tensor(1)$requires_grad_(TRUE)
  )
  expect_failure(expect_equal(
    torch_tensor(1)$requires_grad_(FALSE),
    torch_tensor(1)$requires_grad_(TRUE)
  ))
})`

const rtdal009505Source0003 = `test_that("comparison takes tensor's value into account", {
  testthat::local_edition(3)
  expect_failure(expect_equal(
    torch_tensor(1),
    torch_tensor(2)
  ))
})`

const rtdal009505Source0004 = `test_that("comparison takes tensor's dimension into account", {
  testthat::local_edition(3)
  expect_failure(expect_equal(
    torch_tensor(1)$reshape(c(1, 1)),
    torch_tensor(1)$reshape(1)
  ))
})`

const rtdal009505Source0005 = `test_that("grad_fn is respected", {
  testthat::local_edition(3)
  x = torch_tensor(1)$requires_grad_(TRUE)
  # grad_fn is changed after cloning
  expect_failure(expect_equal(
    x,
    x$clone()
  ))

  # without requires_grad, grad_fn is not changed

  x = torch_tensor(1)
  # grad_fn is changed
  expect_equal(
    x,
    x$clone()
  )
})`

