const rtdal009520Source0003 = `test_that("Can compare dtypes", {
  expect_true(torch_float32() == torch_float())
  expect_false(torch_float() == torch_int())

  expect_false(torch_float32() != torch_float())
  expect_true(torch_float() != torch_int())
})`

const rtdal009520Source0004 = `test_that("Default dtype", {
  x <- torch_randn(10)
  expect_true(x$dtype == torch_float())
  expect_true(torch_get_default_dtype() == torch_float())

  torch_set_default_dtype(torch_float64())
  expect_true(torch_get_default_dtype() == torch_float64())
  x <- torch_randn(10)
  expect_true(x$dtype == torch_float64())

  torch_set_default_dtype(torch_float())
})`

const rtdal009520Source0005 = `test_that("can set select devices using strings", {
  dtypes <- list(
    "float32" = torch_float32(),
    "float" = torch_float(),
    "float64" = torch_float64(),
    "double" = torch_double(),
    "float16" = torch_float16(),
    "half" = torch_half(),
    "bfloat16" = torch_bfloat16(),
    "uint8" = torch_uint8(),
    "int8" = torch_int8(),
    "int16" = torch_int16(),
    "short" = torch_short(),
    "int32" = torch_int32(),
    "int" = torch_int(),
    "int64" = torch_int64(),
    "long" = torch_long(),
    "bool" = torch_bool()
  )
  
  for(i in seq_along(dtypes)) {
    x <- torch_empty(10, 10, dtype = names(dtypes)[i])
    y <- torch_empty(10, 10, dtype = dtypes[[i]])
    
    expect_true(x$device == y$device)  
  }
  
})`

const rtdal009520Source0006 = `test_that("error when comparing dtypes", {

  expect_error(
    NULL == torch_float64(),
    "not a dtype"
  )

})`

const rtdal009520Source0007 = `test_that("is_floating_point works for all floating point types", {
  # All standard floating point types should return TRUE

  expect_true(torch_float()$is_floating_point)
  expect_true(torch_float32()$is_floating_point)
  expect_true(torch_float64()$is_floating_point)
  expect_true(torch_double()$is_floating_point)
  expect_true(torch_float16()$is_floating_point)
  expect_true(torch_half()$is_floating_point)

  expect_true(torch_bfloat16()$is_floating_point)

  # Non-floating point types should return FALSE
  expect_false(torch_int()$is_floating_point)
  expect_false(torch_int32()$is_floating_point)
  expect_false(torch_int64()$is_floating_point)
  expect_false(torch_long()$is_floating_point)
  expect_false(torch_int16()$is_floating_point)
  expect_false(torch_short()$is_floating_point)
  expect_false(torch_int8()$is_floating_point)
  expect_false(torch_uint8()$is_floating_point)
  expect_false(torch_bool()$is_floating_point)
})`

