const rtdal009522Source0002 = "test_that(\"__and__\", {\n  x <- torch_tensor(TRUE)\n  y <- x$`__and__`(x)\n  expect_tensor(y)\n  expect_equal_to_tensor(y, x)\n\n  x <- torch_tensor(c(TRUE, FALSE))\n  y <- x$`__and__`(TRUE)\n  expect_tensor(y)\n  expect_equal_to_tensor(y, x)\n})"

const rtdal009522Source0003 = `test_that("add", {
  x <- torch_tensor(1L, dtype = torch_long())
  expect_equal_to_r(x$add(1L)$to(dtype = torch_int()), 2L)

  x <- torch_tensor(1L, dtype = torch_long())
  expect_error(y <- x$add(1L), regexp = NA)
  expect_true(x$dtype == torch_long())

  x <- torch_tensor(1)
  expect_equal_to_r(x$add(1), 2)
})`

const rtdal009522Source0004 = `test_that("clamp", {
  x <- torch_randn(5)
  expect_error(x$clamp(1), regexp = NA)
})`

const rtdal009522Source0005 = `test_that("clone", {
  x <- torch_randn(10, 10)
  y <- x$clone()

  expect_equal_to_tensor(x, y)
  expect_true(!x$storage()$data_ptr() == y$storage()$data_ptr())
})`

const rtdal009522Source0006 = `test_that("item", {
  x <- torch_tensor(1)
  expect_equal(x$item(), 1)

  x <- torch_tensor(1L)
  expect_equal(x$item(), 1L)

  x <- torch_tensor(TRUE)
  expect_equal(x$item(), TRUE)

  x <- torch_tensor(1.5)
  expect_equal(x$item(), 1.5)

  x <- torch_tensor(1.5, dtype = torch_double())
  expect_equal(x$item(), 1.5)
})`

const rtdal009522Source0007 = `test_that("new_full", {
  x <- torch_randn(2, 2)
  expect_equal_to_tensor(
    x$new_full(c(3, 3), 1),
    torch_ones(3, 3)
  )
})`

const rtdal009522Source0008 = `test_that("permute", {
  x <- torch_randn(2, 3, 4)
  y <- x$permute(c(3, 2, 1))

  expect_tensor_shape(y, c(4, 3, 2))

  expect_error(
    x$permute(c(2, 1, 0)),
    regexp = "Indexing starts at 1 but found a 0.",
    fixed = TRUE
  )
})`

const rtdal009522Source0009 = `test_that("std works", {
  x <- torch_randn(10)
  s <- x$std()
  r <- sd(as.numeric(x))
  expect_equal_to_r(s, r, tolerance = 1e-6)
})`

const rtdal009522Source0010 = `test_that("var works", {
  x <- torch_randn(10)
  s <- x$var()
  r <- var(as.numeric(x))
  expect_equal_to_r(s, r, tolerance = 1e-6)
})`

const rtdal009522Source0011 = `test_that("repeat interleave works with cuda", {
  device <- if (cuda_is_available()) "cuda" else "cpu"
  x <- torch_tensor(c(1, 2, 3), device = device)
  y <- x$repeat_interleave(2L)
  expect_tensor_shape(y, c(6))

  y <- torch_repeat_interleave(x, 2L)
  expect_tensor_shape(y, c(6))
})`

