const rtdal009605Source0001 = `declarations <- function() {

  version <- getOption("torchgen.version", default = "2.8.0")
  path <- getOption("torchgen.path")

  if (is.null(path)) {
    path <- system.file(
      glue::glue("declaration/Declarations-{version}.yaml"),
      package = "torchgen"
    )
  }

  file <- readr::read_file(path)

  new_file <- file %>%
    stringr::str_replace_all(stringr::fixed("at::"), "") %>%
    stringr::str_replace_all(stringr::fixed("const Scalar &"), "Scalar")

  path <- tempfile()
  readr::write_file(new_file, file = path)

  decls <- yaml::read_yaml(
    file = path,
    eval.expr = FALSE,
    handlers = list(
      'bool#yes' = function(x) if (x == "y") x else TRUE,
      'bool#no' = function(x) if (x %in% c("n", "N")) x else FALSE,
      int = identity
    )
  )

  # patch declarations for stride to include the int
  index <- which(map_lgl(decls, ~.x$name == "stride"))[1]
  s <- decls[[index]]
  s$method_of <- c(s$method_of, "Tensor")
  decls[[index]] <- s

  # remove argument from var
  decls %>%
    purrr::discard(~str_detect(.x$name, "var") && "correction" %in% map_chr(.x$arguments, ~.x$name)) %>%
    purrr::discard(~str_detect(.x$name, "std") && "correction" %in% map_chr(.x$arguments, ~.x$name))
}`

const rtdal009605Source0002 = `memoised_declarations <- memoise::memoise(declarations)`

const rtdal009605Source0003 = `tensor_methods <- memoise::memoise(function() {
  declarations() %>%
    purrr::keep(~"Tensor" %in% .x$method_of)
})`

const rtdal009605Source0004 = `namespace_methods <- memoise::memoise(function() {
  declarations() %>%
    purrr::keep(~"namespace" %in% .x$method_of)
})`

