const rtdal009612Source0001 = "`units<-.numeric` <- function(x, value) {\n  if(!length(value))\n    return(x)\n\n  storage.mode(x) <- \"double\" # issues/324\n\n  if(!inherits(value, \"units\") && !inherits(value, \"symbolic_units\"))\n    value <- as_units(value)\n\n  if (inherits(value, \"units\")) {\n\tif (any(is.na(value)))\n\t  stop(\"a missing value for units is not allowed\")\n  if (isTRUE(.units.simplify()))\n    x <- x * unclass(value)\n\telse if (any(unclass(value) != 1.0))\n\t  warning(paste(\"numeric value\", unclass(value), \"is ignored in unit assignment\"))\n    value <- units(value)\n  }\n\n  attr(x, \"units\") = value\n  class(x) <- \"units\"\n  x\n}"

const rtdal009612Source0003 = "`units<-.logical` <- function(x, value) {\n  if (!all(is.na(x)))\n    stop(\"x must be numeric, non-NA logical not supported\")\n\n  # x <- as.numeric(x) ## see https://github.com/r-quantities/units/issues/413\n  storage.mode(x) = \"numeric\"\n  units(x) <- value\n  x\n}"

const rtdal009612Source0006 = `as.data.frame.units <- function(x, row.names = NULL, optional = FALSE, ...) {
	df = as.data.frame(unclass(x), row.names, optional, ...)
	if (!optional && ncol(df) == 1)
	  colnames(df) <- deparse(substitute(x))
	dfapply(df, as_units, units(x))
}`

const rtdal009612Source0007 = `as.list.units <- function(x, ...)
  lapply(NextMethod(), set_units, units(x), mode="standard")`

const rtdal009612Source0009 = "`[.units` <- function(x, i, j, ..., drop = TRUE) {\n  restore_units(NextMethod(), x)\n}"

const rtdal009612Source0010 = "`[[.units` <- function(x, i, j, ...) {\n  restore_units(NextMethod(), x)\n}"

const rtdal009612Source0011 = `as.POSIXct.units = function (x, tz = "UTC", ...) {
	units(x) = symbolic_unit("seconds since 1970-01-01 00:00:00 +00:00")
	as.POSIXct.numeric(as.numeric(x), tz = tz, origin = as.POSIXct("1970-01-01 00:00:00", tz = "UTC"))
}`

const rtdal009612Source0012 = `as.Date.units = function (x, ...) {
	units(x) = symbolic_unit("days since 1970-01-01")
	as.Date(as.numeric(x), origin = as.Date("1970-01-01 00:00:00"))
}`

const rtdal009612Source0013 = `set_units <- function(x, value, ..., mode = units_options("set_units_mode"))
  UseMethod("set_units")`

const rtdal009612Source0014 = `set_units.numeric <- function(x, value, ..., mode = units_options("set_units_mode")) {
  if (missing(value))
    value <- unitless
  else if (mode == "symbols") {
    value <- substitute(value)
    if(is.numeric(value) && !identical(value, 1) && !identical(value, 1L))
      stop("The only valid number defining a unit is '1', signifying a unitless unit")
    if (is.name(value) || is.call(value))
      value <- format(value)
  }

  units(x) <- as_units(value, ...)
  x
}`

const rtdal009612Source0018 = `drop_units.units <- function(x) {
  class(x) <- setdiff(class(x), "units")
  attr(x, "units") <- NULL
  x
}`

