const rtdal009626Source0006 = `Ops.symbolic_units <- function(e1, e2) {
  if (nargs() == 1)
    stop(paste("unary", .Generic, "not defined for \"units\" objects"))

  eq <- switch(.Generic, "==" = , "!=" = TRUE, FALSE)
  if (eq) {
    if (.Generic == "==")
      .same_units(e1, e2)
    else
      !.same_units(e1, e2)
  } else
    stop(paste("operation", .Generic, "not allowed for symbolic operators")) # nocov
}`

const rtdal009626Source0008 = `.pretty_print_sequence <- function(terms, op, neg_power = FALSE, sep = "") {
  pwr_op <- if (op == " ") "" else "^"
  sym <- unique(terms)
  pwr <- tabulate(factor(terms, sym))
  if (neg_power) pwr <- pwr * -1

  for (i in seq_along(sym)) if (pwr[i] != 1)
    sym[i] <- paste(sym[i], pwr[i], sep = pwr_op)

  s <- matrix(c(sym, rep(paste0(op, sep), length(sym)-1), ""), nrow=length(sym))
  if (!units_options("strict_tokenizer"))
    s[sym >= "0" & sym <= "9", 2] <- ""
  paste0(t(s), collapse="")
}`

const rtdal009626Source0009 = "as.character.symbolic_units <- function(x, ...,\n                                        neg_power = units_options(\"negative_power\"),\n                                        escape_units = FALSE, prod_sep = \"*\", plot_sep = \"\") {\n  sep <- plot_sep\n\n  numerator <- x$numerator[x$numerator != \"1\"]\n  denominator <- x$denominator[x$denominator != \"1\"]\n  if (escape_units) {\n    numerator <- unlist(Map(function(name) paste0(\"`\", name, \"`\", sep = \"\"), numerator))\n    denominator <- unlist(Map(function(name) paste0(\"`\", name, \"`\", sep = \"\"), denominator))\n  }\n\n  if (x == unitless) { # xxx\n    u <- if (escape_units)\n      unlist(Map(function(name) paste0(\"`\", name, \"`\", sep = \"\"),\n                 units_options(\"unitless_symbol\")))\n    else\n      units_options(\"unitless_symbol\")\n    return(u)\n  }\n\n  num_str <- denom_str <- character(0)\n\n  num_str <- if (length(numerator) > 0)\n    .pretty_print_sequence(numerator, prod_sep, FALSE, plot_sep)\n  else if (! neg_power) \"1\" # only denominator: 1/(cm^2*h)\n\n  if (length(denominator) > 0) {\n    sep <- if (neg_power)\n      paste0(prod_sep, plot_sep) else \"/\"\n    denom_str <- .pretty_print_sequence(denominator, prod_sep, neg_power, plot_sep)\n    if (!neg_power && length(unique(denominator)) > 1)\n      denom_str <- paste0(\"(\", denom_str, \")\")\n  }\n\n  if (length(num_str) == 0)\n    denom_str\n  else if (length(denom_str) == 0)\n    num_str\n  else\n    paste(num_str, denom_str, sep = sep)\n}"

const rtdal009626Source0010 = `.simplify_units <- function(value, sym_units) {
  # from R >= 3.5
  isFALSE <- function(x) is.logical(x) && length(x) == 1L && !is.na(x) && !x

  if (isFALSE(.units.simplify())) {
    value = unclass(value)
    units(value) = sym_units
    return(value)
  }

  # This is just a brute force implementation that takes each element in the
  # numerator and tries to find a value in the denominator that can be converted
  # to the same unit. It modifies "value" to rescale the nominator to the denominator
  # before removing matching units.

  drop_ones = function(u) u[ u != "1" ]
  class(value) <- "units"

  new_numerator <- drop_ones(sym_units$numerator)
  new_denominator <- drop_ones(sym_units$denominator)
  delete_num <- c()
  for (i in seq_along(new_numerator)) {
    str1 <- new_numerator[i]

    for (j in seq_along(new_denominator)) {
      str2 <- new_denominator[j]

      if (ud_are_same(str1, str2)) {
        attr(value, "units") <- units(as_units(str1))
        units(value) <- str2
        delete_num <- c(delete_num, i)
        new_denominator <- new_denominator[-j]
        break
      }

    }
  }
  if (length(delete_num) > 0)
    new_numerator <- new_numerator[-delete_num]

  as_units(drop_units(value), .symbolic_units(new_numerator, new_denominator))
}`

