const rtdal009628Source0001 = "ud_are_convertible <- function(from, to, ...) {\n  if (length(dots <- list(...))) {\n    if (exists(\"x\", dots)) from <- dots$x\n    if (exists(\"y\", dots)) to   <- dots$y\n    warning(\"variables `x` and `y` were unfortunate names, and are deprecated\",\n            \"; please use `from` and `to` instead\")\n  }\n  mapply(ud_convertible, ud_char(from), ud_char(to), USE.NAMES=FALSE)\n}"

const rtdal009628Source0003 = `ud_char <- function(x) {
  if (is.character(x)) return(x)
  if (!inherits(x, "symbolic_units")) stop("not a unit")

  # using * instead of space to workaround #414
  res <- if (length(x$numerator))
    paste(x$numerator, collapse="*") else "1"
  if (length(x$denominator))
    res <- paste0(res, "*(", paste(x$denominator, collapse="*"), ")-1")
  res
}`

