const rtdal009663Source0001 = `test_that("'format' can handle short text", {
  raw <- c(NA, "", "a", "foo", "short text")

  expect_equal(
    utf8_format(raw, justify = "none", na.print = "NA"),
    format(raw, justify = "none")
  )

  expect_equal(
    utf8_format(raw, justify = "left", na.print = "NA"),
    format(raw, justify = "left")
  )

  expect_equal(
    utf8_format(raw, justify = "centre", na.print = "NA"),
    format(raw, justify = "centre")
  )

  expect_equal(
    utf8_format(raw, justify = "right", na.print = "NA"),
    format(raw, justify = "right")
  )
})`

const rtdal009663Source0002 = "test_that(paste0(\"'format' can handle long text in Unicode locale\"), {\n  if (l10n_info()$`UTF-8`) {\n    local_utf8()\n    expect_true(cli::is_utf8_output())\n    mapper <- identity\n    variant <- \"unicode\"\n  } else {\n    mapper <- function(x) lapply(x, charToRaw)\n    variant <- \"ansi\"\n  }\n\n  skip_if_not_installed(\"testthat\", \"3.1.1\")\n\n  expect_snapshot(variant = variant, {\n    raw <- c(\n      NA,\n      \"\",\n      \"a\",\n      \"ab\",\n      \"foo\",\n      \"food\",\n      \"short text\",\n      \"\\u6027\",\n      \"\\u6027\\u6027\",\n      \"\\u6027?\"\n    )\n    Encoding(raw) <- \"UTF-8\"\n\n    body(mapper)\n\n    mapper(utf8_format(raw, chars = 2, justify = \"none\", na.print = \"NA\"))\n    mapper(utf8_format(raw, chars = 2, justify = \"left\", na.print = \"NA\"))\n    mapper(utf8_format(raw, chars = 2, justify = \"centre\", na.print = \"NA\"))\n    mapper(utf8_format(raw, chars = 2, justify = \"right\", na.print = \"NA\"))\n  })\n})"

const rtdal009663Source0003 = `test_that("'format' can handle long text in UTF-8 locale, part 2", {
  raw <- c(
    NA,
    "",
    "a",
    "\n",
    "ab",
    "foo",
    "food",
    "short text",
    "\u6027",
    "\u6027\u6027",
    "\u6027?"
  )
  short <- c(
    NA,
    "",
    "a",
    "\u2026",
    "a\u2026",
    "f\u2026",
    "f\u2026",
    "s\u2026",
    "\u2026",
    "\u2026",
    "\u2026"
  )
  rshort <- c(
    NA,
    "",
    "a",
    "\u2026",
    "\u2026b",
    "\u2026o",
    "\u2026d",
    "\u2026t",
    "\u2026",
    "\u2026",
    "\u2026?"
  )

  local_ctype("UTF-8")

  expect_equal(
    utf8_format(raw, chars = 1, justify = "none", na.encode = FALSE),
    format(short, justify = "none", na.encode = FALSE)
  )

  expect_equal(
    utf8_format(raw, chars = 1, justify = "left", na.encode = FALSE),
    format(short, justify = "left", na.encode = FALSE)
  )

  expect_equal(
    utf8_format(raw, chars = 1, justify = "centre", na.encode = FALSE),
    format(short, justify = "centre", na.encode = FALSE)
  )

  expect_equal(
    utf8_format(raw, chars = 1, justify = "right", na.encode = FALSE),
    format(rshort, justify = "right", na.encode = FALSE)
  )
})`

const rtdal009663Source0004 = `test_that("'format' can handle long text in C locale", {
  #            6         7          8           9            10
  raw <- c(
    "\u6027",
    "?\u6027",
    "\n\u6027",
    "?\n\u6027",
    "\u0001\u6027",
    "\u6027?",
    "\u6027\n",
    "\u6027?\n",
    "\u6027\u0001"
  )
  short <- c(
    "\\u6027",
    "?\\u6027",
    "\\n\\u6027",
    "?\\n...",
    "\\u0001...",
    "\\u6027?",
    "\\u6027\\n",
    "\\u6027?...",
    "\\u6027..."
  )
  rshort <- c(
    "\\u6027",
    "?\\u6027",
    "\\n\\u6027",
    "...\\n\\u6027",
    "...\\u6027",
    "\\u6027?",
    "\\u6027\\n",
    "...?\\n",
    "...\\u0001"
  )

  skip_on_os("windows")

  # https://github.com/r-lib/testthat/issues/1285
  with_ctype("C", {
    short_format <- utf8_encode(utf8_format(raw, chars = 8, justify = "none"))
    left <- utf8_encode(utf8_format(raw, chars = 8, justify = "left"))
    centre <- utf8_encode(utf8_format(raw, chars = 8, justify = "centre"))
    right <- utf8_encode(utf8_format(raw, chars = 8, justify = "right"))
  })

  expect_equal(short_format, format(short, justify = "none"))

  expect_equal(sub("\\s+$", "", left), short)
  expect_equal(as.numeric(nchar(left)), rep(10, length(raw)))

  expect_equal(sub("^\\s+", "", sub("\\s+$", "", centre)), short)
  expect_equal(as.numeric(nchar(centre)), rep(10, length(raw)))

  expect_equal(sub("^\\s+", "", right), rshort)
  expect_equal(as.numeric(nchar(right)), rep(11, length(raw)))
})`

