const rtdal009684Source0044 = "cnd_body.vctrs_error_names_must_be_unique <- function(cnd, ...) {\n  names <- cnd$names\n\n  dups <- vec_group_loc(names)\n  dup_indicator <- map_lgl(dups$loc, function(x) length(x) != 1L)\n  dups <- vec_slice(dups, dup_indicator)\n\n  header <- \"These names are duplicated:\"\n  header <- c(x = header)\n  header <- format_error_bullets(header)\n\n  info <- map2_chr(dups$key, dups$loc, make_names_loc_bullet)\n\n  message <- bullets(info, header = header)\n  message <- indent(message, 2)\n\n  arg <- arg_as_string(cnd$arg)\n  if (arg != \"\") {\n    hint <- c(\n      i = glue::glue(\"Use argument `{cnd$arg}` to specify repair strategy.\")\n    )\n    message <- c(message, format_error_bullets(hint))\n  }\n\n  message\n}"

const rtdal009684Source0045 = `make_names_loc_bullet <- function(x, loc) {
  if (length(loc) == 1) {
    glue::glue("{glue::double_quote(x)} at location {loc}.")
  } else {
    glue::glue(
      "{glue::double_quote(x)} at locations {ensure_full_stop(enumerate(loc))}"
    )
  }
}`

const rtdal009684Source0046 = `enumerate <- function(x, max = 5L, allow_empty = FALSE) {
  n <- length(x)

  if (n == 0L && !allow_empty) {
    abort("Internal error: Enumeration can't be empty.")
  }
  if (n > max) {
    paste0(glue::glue_collapse(x[seq2(1, max)], ", "), ", etc.")
  } else {
    if (n == 2) {
      last <- " and "
    } else {
      last <- ", and "
    }
    glue::glue_collapse(x, ", ", last = last)
  }
}`

const rtdal009684Source0047 = `ensure_full_stop <- function(x) {
  n <- nchar(x)
  if (substr(x, n, n) == ".") {
    x
  } else {
    paste0(x, ".")
  }
}`

